const items = $input.all();

const names = { 'bbc': 'BBC Business', 'dawn': 'Dawn Business', 'cnbc': 'CNBC Finance' };
const grouped = {};

for (const item of items) {
  const j = item.json;
  const link = j.link || '';
  const host = (link.match(/https?:\/\/([^\/]+)/) || [])[1] || 'unknown';
  const key = Object.keys(names).find(k => host.includes(k)) || host;
  const source = names[key] || host;
  if (!grouped[source]) grouped[source] = [];
  grouped[source].push(j);
}

let text = '';
let count = 0;
for (const [source, list] of Object.entries(grouped)) {
  list.sort((a, b) => new Date(b.isoDate || 0) - new Date(a.isoDate || 0));
  text += `## ${source}\n`;
  for (const a of list.slice(0, 6)) {
    const snippet = (a.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 200);
    text += `- ${a.title} | ${snippet} | ${a.link}\n`;
    count++;
  }
  text += '\n';
}

return [{ json: { headlines: text.trim(), count } }];

const raw = ($json.text || '').replace(/\x60{3}(html)?/gi, '').trim();
const count = $('Prepare headlines').first().json.count || 0;
const dateStr = $now.setZone('Asia/Karachi').toFormat('cccc, d LLLL yyyy');

const edition = $now.setZone('Asia/Karachi').toFormat('ccc d LLL');
const timeStr = $now.setZone('Asia/Karachi').toFormat('HH:mm');
const mono = 'font-family:Consolas,Menlo,Courier New,monospace;';
const label = 'font-family:Trebuchet MS,Verdana,Tahoma,sans-serif;';
const serif = 'font-family:Georgia,Cambria,Times New Roman,serif;';
const body = 'font-family:Segoe UI,Helvetica,Arial,sans-serif;';

const accents = [
  { c: '#22d3ee', g: 'linear-gradient(90deg,#22d3ee,#818cf8)', icon: '&#9670;', bg: '#072a36', item: '#0b3a4a', badge: '#0e7490' },
  { c: '#d8b4fe', g: 'linear-gradient(90deg,#c084fc,#f472b6)', icon: '&#9650;', bg: '#22123d', item: '#2e1a52', badge: '#7e22ce' },
  { c: '#6ee7b7', g: 'linear-gradient(90deg,#34d399,#22d3ee)', icon: '&#9679;', bg: '#06291f', item: '#0b3b2d', badge: '#047857' },
  { c: '#fcd34d', g: 'linear-gradient(90deg,#fbbf24,#fb7185)', icon: '&#9733;', bg: '#2e2108', item: '#3d2c0c', badge: '#b45309' }
];

const styleContent = (html, a) => html
  .replace(/<ul[^>]*>/gi, '<ul style="margin:0;padding-left:0;list-style:none;">')
  .replace(/<li[^>]*>/gi, '<li style="' + body + 'margin:0 0 14px;padding:16px 18px;background-color:' + a.item + ';border-left:5px solid ' + a.c + ';border-radius:12px;line-height:1.7;color:#f1f5f9;font-size:18px;">')
  .replace(/<p[^>]*>/gi, '<p style="' + body + 'margin:0 0 14px;padding:16px 18px;background-color:' + a.item + ';border-left:5px solid ' + a.c + ';border-radius:12px;line-height:1.7;color:#f1f5f9;font-size:18px;">')
  .replace(/<(b|strong)>/gi, '<b style="' + serif + 'color:' + a.c + ';font-size:20px;font-weight:700;">')
  .replace(/<\/strong>/gi, '</b>')
  .replace(/<a /gi, '<a target="_blank" style="' + label + 'display:inline-block;margin-top:6px;padding:4px 12px;background-color:' + a.badge + ';color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;letter-spacing:0.5px;border-radius:999px;" ')
  .replace(/>Read more</gi, '>Read more &#8599;<');

const parts = raw.split(/<h3[^>]*>/i).filter(s => s.trim());
let cards = '';
parts.forEach((part, i) => {
  const a = accents[i % accents.length];
  const end = part.toLowerCase().indexOf('</h3>');
  const title = end >= 0 ? part.slice(0, end).replace(/<[^>]+>/g, '').trim() : '';
  const content = (end >= 0 ? part.slice(end + 5) : part).trim();
  if (!title && !content) return;
  cards += '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 22px;background-color:' + a.bg + ';border:1px solid ' + a.badge + ';border-radius:18px;overflow:hidden;">'
    + '<tr><td style="height:5px;line-height:5px;font-size:0;background-color:' + a.c + ';background-image:' + a.g + ';">&nbsp;</td></tr>'
    + '<tr><td style="padding:22px 24px 10px;">'
    + (title ? '<div style="margin-bottom:18px;"><span style="' + label + 'display:inline-block;padding:6px 14px;background-color:' + a.badge + ';color:#ffffff;font-size:14px;font-weight:700;letter-spacing:2px;border-radius:8px;">' + a.icon + '&nbsp; 0' + (i + 1) + '</span>'
      + '<span style="' + serif + 'display:inline-block;margin-left:12px;font-size:24px;font-weight:700;color:' + a.c + ';vertical-align:middle;">' + title + '</span></div>' : '')
    + styleContent(content, a)
    + '</td></tr></table>';
});

const chip = (name, value, fill, txt) => '<td width="33%" style="padding:0 5px;"><div style="background-color:' + fill + ';border-radius:14px;padding:14px 8px;text-align:center;">'
  + '<div style="' + label + 'font-size:13px;font-weight:700;letter-spacing:2px;color:' + txt + ';">' + name + '</div>'
  + '<div style="' + serif + 'font-size:24px;font-weight:700;color:#ffffff;margin-top:6px;">' + value + '</div></div></td>';

const html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#05070f;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#05070f;padding:28px 12px;font-family:Segoe UI,Helvetica,Arial,sans-serif;"><tr><td align="center">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:660px;">'
  + '<tr><td style="background-color:#0b1024;background-image:linear-gradient(135deg,#0b1024 0%,#1e1b4b 55%,#0e7490 100%);border:1px solid #1e293b;border-radius:20px;padding:34px 30px 26px;">'
  + '<div style="' + label + 'font-size:14px;letter-spacing:4px;color:#67e8f9;font-weight:700;">&#9670; AI MARKET INTELLIGENCE</div>'
  + '<div style="' + serif + 'font-size:40px;line-height:1.15;font-weight:700;color:#ffffff;margin-top:12px;">Finance News Digest</div>'
  + '<div style="width:72px;height:3px;line-height:3px;font-size:0;margin-top:14px;border-radius:3px;background-color:#22d3ee;background-image:linear-gradient(90deg,#22d3ee,#c084fc);">&nbsp;</div>'
  + '<div style="' + label + 'font-size:17px;color:#e0e7ff;margin-top:14px;">' + dateStr + '</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:22px;"><tr>'
  + chip('HEADLINES', count, '#0e7490', '#cffafe') + chip('SOURCES', '03', '#7e22ce', '#f3e8ff') + chip('EDITION', edition, '#b45309', '#fef3c7')
  + '</tr></table>'
  + '</td></tr>'
  + '<tr><td style="height:20px;line-height:20px;font-size:0;">&nbsp;</td></tr>'
  + '<tr><td>' + cards + '</td></tr>'
  + '<tr><td style="padding:18px 8px 6px;text-align:center;' + label + 'font-size:14px;line-height:1.9;letter-spacing:1px;color:#94a3b8;">'
  + '// SIGNAL SOURCES: BBC BUSINESS &middot; DAWN &middot; CNBC<br>'
  + 'Compiled by AI at ' + timeStr + ' PKT &middot; Not investment advice'
  + '</td></tr>'
  + '</table></td></tr></table></body></html>';

return [{ json: { html } }];
